package ir.ghiyas.alimaa.data

import ir.ghiyas.alimaa.domain.models.CalendarType
import ir.ghiyas.alimaa.domain.models.QuoteItem
import ir.ghiyas.alimaa.domain.models.WorkCalendarProfile
import ir.ghiyas.alimaa.domain.models.WorkTurn
import kotlinx.browser.window
import kotlin.js.json

object WorkCalendarRepository {
    private const val STORAGE_KEY = "ghiyas_work_calendars"

    fun saveProfile(profile: WorkCalendarProfile) {
        val profiles = getAllProfiles().toMutableList()
        if (profile.isDefault) {
            for (i in profiles.indices) profiles[i] = profiles[i].copy(isDefault = false)
        }
        val existingIndex = profiles.indexOfFirst { it.id == profile.id }
        if (existingIndex >= 0) {
            profiles[existingIndex] = profile
        } else {
            val finalProfile = if (profiles.isEmpty()) profile.copy(isDefault = true) else profile
            profiles.add(finalProfile)
        }
        saveAll(profiles)
    }

    fun deleteProfile(id: String) {
        val profiles = getAllProfiles().filter { it.id != id }.toMutableList()
        if (profiles.isNotEmpty() && profiles.none { it.isDefault }) {
            profiles[0] = profiles[0].copy(isDefault = true)
        }
        saveAll(profiles)
    }

    fun getAllProfiles(): List<WorkCalendarProfile> {
        val jsonString = window.localStorage.getItem(STORAGE_KEY)
        if (jsonString.isNullOrBlank() || jsonString == "null" || jsonString == "undefined" || jsonString == "{}" || jsonString == "[]") {
            return emptyList()
        }
        
        return try {
            val parsed = JSON.parse<dynamic>(jsonString)
            if (parsed == null || !js("Array.isArray(parsed)").unsafeCast<Boolean>()) {
                return emptyList()
            }
            
            // استفاده از dynamic برای جلوگیری از خطای length کامپایلر و جلوگیری از کرش size در مرورگر
            val jsArray: dynamic = parsed
            val len = jsArray.length as Int
            val resultList = mutableListOf<WorkCalendarProfile>()
            for (i in 0 until len) {
                resultList.add(jsToProfile(jsArray[i]))
            }
            resultList
        } catch (e: Throwable) { 
            console.error("Critical error parsing database. Returning empty to avoid freeze.", e)
            emptyList()
        }
    }

    private fun saveAll(profiles: List<WorkCalendarProfile>) {
        try {
            val jsArray = profiles.map { profileToJs(it) }.toTypedArray()
            window.localStorage.setItem(STORAGE_KEY, js("JSON.stringify(jsArray)") as String)
        } catch (e: Throwable) {
            console.error("Error saving profiles", e)
        }
    }

    private fun profileToJs(profile: WorkCalendarProfile): dynamic {
        val scheduleArray = profile.schedule.map { 
            json("turnId" to it.turnId, "cycle" to it.cycle, "owner" to it.owner, "notes" to it.notes)
        }.toTypedArray()

        val quotesArray = profile.quotes.map {
            json("text" to it.text, "translation" to it.translation, "source" to it.source)
        }.toTypedArray()

        return json(
            "id" to profile.id,
            "name" to profile.name,
            "isDefault" to profile.isDefault,
            "type" to profile.type.name,
            "startYear" to profile.startYear,
            "startMonth" to profile.startMonth,
            "startDay" to profile.startDay,
            "turnTime" to profile.turnTime,
            "shiftBeforeTemplate" to profile.shiftBeforeTemplate,
            "shiftAfterTemplate" to profile.shiftAfterTemplate,
            "schedule" to scheduleArray,
            "quotes" to quotesArray
        )
    }

    private fun jsToProfile(jsObj: dynamic): WorkCalendarProfile {
        val parsedSchedule = mutableListOf<WorkTurn>()
        val scheduleJs = jsObj.schedule
        if (scheduleJs != undefined && scheduleJs != null && js("Array.isArray(scheduleJs)").unsafeCast<Boolean>()) {
            val arr: dynamic = scheduleJs
            val len = arr.length as Int
            for (i in 0 until len) {
                val it = arr[i]
                parsedSchedule.add(
                    WorkTurn(
                        turnId = if (it.turnId != undefined) it.turnId.toString().toIntOrNull() ?: 0 else 0,
                        cycle = if (it.cycle != undefined) it.cycle.toString().toIntOrNull() ?: 0 else 0,
                        owner = if (it.owner != undefined && it.owner != null) it.owner.toString() else "ناشناس",
                        notes = if (it.notes != undefined && it.notes != null) it.notes.toString() else ""
                    )
                )
            }
        }

        val parsedQuotes = mutableListOf<QuoteItem>()
        val quotesJs = jsObj.quotes
        if (quotesJs != undefined && quotesJs != null && js("Array.isArray(quotesJs)").unsafeCast<Boolean>()) {
            val arr: dynamic = quotesJs
            val len = arr.length as Int
            for (i in 0 until len) {
                val it = arr[i]
                parsedQuotes.add(
                    QuoteItem(
                        text = if (it.text != undefined && it.text != null) it.text.toString() else "",
                        translation = if (it.translation != undefined && it.translation != null) it.translation.toString() else "",
                        source = if (it.source != undefined && it.source != null) it.source.toString() else ""
                    )
                )
            }
        }

        val typeStr = if (jsObj.type != undefined && jsObj.type != null) jsObj.type.toString() else CalendarType.DAY_BASED.name
        val cType = try { CalendarType.valueOf(typeStr) } catch (e: Throwable) { CalendarType.DAY_BASED }

        return WorkCalendarProfile(
            id = if (jsObj.id != undefined && jsObj.id != null) jsObj.id.toString() else "calc_${kotlin.js.Date().getTime()}",
            name = if (jsObj.name != undefined && jsObj.name != null) jsObj.name.toString() else "",
            isDefault = if (jsObj.isDefault != undefined) jsObj.isDefault as Boolean else false,
            type = cType,
            startYear = if (jsObj.startYear != undefined) jsObj.startYear.toString().toIntOrNull() ?: 0 else 0,
            startMonth = if (jsObj.startMonth != undefined) jsObj.startMonth.toString().toIntOrNull() ?: 0 else 0,
            startDay = if (jsObj.startDay != undefined) jsObj.startDay.toString().toIntOrNull() ?: 0 else 0,
            turnTime = if (jsObj.turnTime != undefined && jsObj.turnTime != null) jsObj.turnTime.toString() else "",
            shiftBeforeTemplate = if (jsObj.shiftBeforeTemplate != undefined && jsObj.shiftBeforeTemplate != null) jsObj.shiftBeforeTemplate.toString() else "",
            shiftAfterTemplate = if (jsObj.shiftAfterTemplate != undefined && jsObj.shiftAfterTemplate != null) jsObj.shiftAfterTemplate.toString() else "",
            schedule = parsedSchedule,
            quotes = parsedQuotes
        )
    }
}
